def __call__(self, buf: ReceiveBuffer) -> Union[Data, EndOfMessage, None]:
    if self._remaining == 0:
        return EndOfMessage()
    data = buf.maybe_extract_at_most(self._remaining)
    if data is None:
        return None
    self._remaining -= len(data)
    return Data(data=data)

